<?php require_once __DIR__.'/includes/database.php';require_once __DIR__.'/includes/functions.php';require_once __DIR__.'/includes/images.php';$pageTitle=t('Sermons','ስብከቶች');$rows=[];try{$rows=db()->query("SELECT * FROM sermons WHERE status='published' ORDER BY created_at DESC")->fetchAll();}catch(Throwable $e){}function yt_embed($url){if(!$url)return '';if(preg_match('~(?:youtu\.be/|youtube\.com/(?:watch\?v=|embed/|shorts/))([^?&/]+)~',$url,$m))return 'https://www.youtube.com/embed/'.rawurlencode($m[1]);return '';}require __DIR__.'/includes/header.php';?>
<section class="page-hero page-hero-image" style="<?=e(hero_style('sermons'))?>"><div class="container"><span class="eyebrow"><?=e(t('Home / Sermons','መነሻ / ስብከቶች'))?></span><h1><?=e(t('Sermons','ስብከቶች'))?></h1><p><?=e(t('Listen, learn and live the Word of God through messages from the fellowship.','ከፌሎሽፑ መልእክቶች የእግዚአብሔርን ቃል ያዳምጡ፣ ይማሩና በሕይወት ይኑሩ።'))?></p></div></section>
<section class="section"><div class="container"><div class="cards"><?php if(!$rows):?><div class="card"><h3><?=e(t('No sermons published yet','እስካሁን የታተሙ ስብከቶች የሉም'))?></h3></div><?php else:foreach($rows as $r):$embed=yt_embed($r['video_url']??'');?><article class="card"><?php if($embed):?><div style="aspect-ratio:16/9;margin:-23px -23px 17px"><iframe width="100%" height="100%" src="<?=e($embed)?>" title="<?=e(text_lang($r,'title'))?>" frameborder="0" allowfullscreen></iframe></div><?php else:?><div class="icon-box">▶</div><?php endif;?><span class="tag"><?=e($r['bible_reference']?:'SERMON')?></span><h3><?=e(text_lang($r,'title'))?></h3><p><?=e(text_lang($r,'description'))?></p><small><?=e($r['speaker']?:'Fellowship Speaker')?></small><?php if(!empty($r['audio_url'])):?><p><audio controls style="width:100%" src="<?=e($r['audio_url'])?>"></audio></p><?php endif;?></article><?php endforeach;endif;?></div></div></section><?php require __DIR__.'/includes/footer.php';?>
